// LC 3。不变量：s[left, right] 内每个字符最多出现一次。
// 换题时只改 while 的非法条件：种类数超限见「至多 k 种」模板；若要区间本身，额外记 bestLeft。
static int lengthOfLongestSubstring(String s) {
    int[] freq = new int[128];
    int left = 0;
    int best = 0;
    for (int right = 0;
    right < s.length();
    right++) {
        char in = s.charAt(right);
        freq[in]++;
        // 只把左端推到“刚进来的这个字符”重新唯一，不必把别的字符也清掉
        while (freq[in] > 1) {
            freq[s.charAt(left)]--;
            left++;
        }
        best = Math.max(best, right - left + 1);
        // 窗口已经合法，最长在这里更新
    }
    return best;
}

// LC 76。不变量：formed == needKinds 时，窗口已覆盖 t 里每种字符的需要次数。
// 换 209：删掉 need/formed，改记 sum，sum >= target 时更新长度并 sum -= nums[left++]。
// 换覆盖变种：计数下标从 char 改成题目的元素键，入窗/出窗仍要成对加减。
static String minWindow(String s, String t) {
    if (t.isEmpty() || s.length() < t.length()) {
        return "";
    }
    int[] need = new int[128];
    int needKinds = 0;
    for (int i = 0;
    i < t.length();
    i++) {
        if (need[t.charAt(i)]++ == 0) {
            needKinds++;
        }
    }
    int[] window = new int[128];
    int formed = 0;
    int left = 0;
    int bestLen = Integer.MAX_VALUE;
    int bestLeft = 0;
    for (int right = 0;
    right < s.length();
    right++) {
        char in = s.charAt(right);
        window[in]++;
        // 次数刚好凑齐才 +1；超出 need 或 t 里根本没有的字符都不计
        if (need[in] > 0 && window[in] == need[in]) {
            formed++;
        }
        while (formed == needKinds) {
            // 仍然覆盖：先记答案，再尝试丢左端
            if (right - left + 1 < bestLen) {
                bestLen = right - left + 1;
                bestLeft = left;
            }
            char out = s.charAt(left++);
            window[out]--;
            if (need[out] > 0 && window[out] < need[out]) {
                formed--;
            }
        }
    }
    return bestLen == Integer.MAX_VALUE ? "" : s.substring(bestLeft, bestLeft + bestLen);
}

// LC 438，输入仅小写字母。窗口长度恒为 p.length()，合法条件是 26 槽与 p 完全相等。
// 换 567：equals 成立立刻 return true，扫完 return false。
// 出现大写或非字母时改成 int[128]，下标直接用字符，不要减 'a'。
static java.util.List<Integer> findAnagrams(String s, String p) {
    java.util.List<Integer> ans = new java.util.ArrayList<>();
    int n = s.length();
    int m = p.length();
    if (m == 0 || n < m) {
        return ans;
    }
    int[] need = new int[26];
    int[] window = new int[26];
    for (int i = 0;
    i < m;
    i++) {
        need[p.charAt(i) - 'a']++;
    }
    for (int i = 0;
    i < n;
    i++) {
        window[s.charAt(i) - 'a']++;
        if (i >= m) {
            window[s.charAt(i - m) - 'a']--;
            // 右端进来一个，左端必须出去一个
        }
        if (i >= m - 1 && java.util.Arrays.equals(window, need)) {
            ans.add(i - m + 1);
        }
    }
    return ans;
}

// LC 340。不变量：窗口内不同字符数 <= k。超标才收缩，收缩后更新最大长度。
// 换 904：k 固定为 2。水果种类不是 ASCII 时，freq 改成 Map<Integer,Integer>：
// 计数从 0 变为 1 时 distinct++，减到 0 时 distinct--，其余与下面相同。
static int lengthOfLongestKDistinct(String s, int k) {
    if (k <= 0 || s.isEmpty()) {
        return 0;
    }
    int[] freq = new int[128];
    int distinct = 0;
    int left = 0;
    int best = 0;
    for (int right = 0;
    right < s.length();
    right++) {
        char in = s.charAt(right);
        if (freq[in] == 0) {
            distinct++;
        }
        freq[in]++;
        while (distinct > k) {
            char out = s.charAt(left++);
            freq[out]--;
            if (freq[out] == 0) {
                distinct--;
            }
        }
        best = Math.max(best, right - left + 1);
    }
    return best;
}

